import { Group, Mesh, CylinderGeometry, TorusKnotGeometry, PlaneGeometry, MeshStandardMaterial, MeshBasicMaterial, Texture, Color } from 'three/webgpu';
import {
    ColorNode,
    TextureNode,
    FloatNode,
    MixNode,
    StandardMaterialNode,
    UVNode,
    Vector2Node,
    LengthNode,
    OperatorNode,
    AddNode,
    SubtractNode,
    DivideNode,
    MultiplyNode,
    PowNode,
    ClampNode,
    TransformNode,
    NormalMapNode,
    AnisotropyNode
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{ headline: string, caption: string }} textContent
 * @property {{ cinematicPrimitives: Array<{ name: string, params: any }> }} cinematicPrimitives
 * @property {{ imageUrl: string }} assets
 */

/**
 * @typedef {Object} NodeContext
 * @property {function(string): Texture} textureLoader
 * @property {Object<string, function(THREE.Object3D, any): void>} primitives
 * @property {Object} fontAtlas
 */

export default function createNode(config, ctx) {
    const group = new Group();
    group.name = 'PedestalMaterialStudy';

    // ---------- Textures ----------
    const brushedTex = ctx.textureLoader('/prism-assets/chrome/brushed-metal.map.png');
    brushedTex.wrapS = brushedTex.wrapT = 1000; // RepeatWrapping

    // ---------- Pedestal ----------
    const pedestalGeom = new CylinderGeometry(1.1, 1.1, 0.5, 64, 1, false);
    const pedestalMat = new MeshStandardMaterial({
        color: new Color('#14141a'),
        roughness: 0.7,
        metalness: 0.35
    });
    const pedestalMesh = new Mesh(pedestalGeom, pedestalMat);
    // top face at y = -0.35  → center = -0.35 - height/2
    pedestalMesh.position.y = -0.35 - 0.25;
    group.add(pedestalMesh);

    // ---------- Torus Knot ----------
    const knotGeom = new TorusKnotGeometry(0.7, 0.22, 220, 36);
    // Node‑based material for brushed metal
    const roughnessMapNode = new TextureNode(brushedTex);
    const roughnessMulNode = new MultiplyNode(new FloatNode(0.9), roughnessMapNode);
    const roughnessNode = new MixNode(new FloatNode(0.55), roughnessMulNode, new FloatNode(1.0));

    const metalnessNode = new FloatNode(0.55);
    const clearcoatNode = new FloatNode(0.22);
    const clearcoatRoughNode = new FloatNode(0.35);

    // anisotropy (simulated via anisotropy texture rotation)
    const anisotropyNode = new AnisotropyNode({
        strength: new FloatNode(0.9),
        direction: new Vector2Node(0.0, 1.0) // rotated 90° to tube direction
    });

    const baseColorNode = new ColorNode('#16161d');

    const metalMatNode = new StandardMaterialNode();
    metalMatNode.color = baseColorNode;
    metalMatNode.roughness = roughnessNode;
    metalMatNode.metalness = metalnessNode;
    metalMatNode.clearcoat = clearcoatNode;
    metalMatNode.clearcoatRoughness = clearcoatRoughNode;
    metalMatNode.anisotropy = anisotropyNode;

    // Imperfection pass – scratch‑noise normal map (placeholder using same texture)
    const normalMapNode = new NormalMapNode(new TextureNode(brushedTex));
    metalMatNode.normal = normalMapNode;
    metalMatNode.normalScale = new Vector2Node(0.15, 0.15);

    const knotMesh = new Mesh(knotGeom);
    knotMesh.material = metalMatNode;
    knotMesh.position.set(0, 0.4, 0);
    group.add(knotMesh);

    // ---------- Contact Shadow ----------
    const shadowGeom = new PlaneGeometry(3, 3, 1, 1);
    const shadowMat = new MeshBasicMaterial({
        color: new Color('#000000'),
        transparent: true,
        opacity: 0.6,
        depthWrite: false
    });
    const shadowMesh = new Mesh(shadowGeom, shadowMat);
    shadowMesh.rotation.x = -Math.PI / 2;
    shadowMesh.position.y = -0.36;
    group.add(shadowMesh);

    // ---------- Backdrop Gradient ----------
    const backdropGeom = new PlaneGeometry(7, 6, 1, 1);
    const gradNode = (() => {
        const uv = new UVNode();
        const y = uv.y;
        const stop0 = new ColorNode('#0b0b10');
        const stop1 = new ColorNode('#101017');
        const stop2 = new ColorNode('#16161d');
        const mix0 = new MixNode(stop0, stop1, new DivideNode(y, new FloatNode(0.7)));
        return new MixNode(mix0, stop2, new SubtractNode(y, new FloatNode(0.7)));
    })();
    const backdropMatNode = new StandardMaterialNode();
    backdropMatNode.color = gradNode;
    const backdropMat = backdropMatNode;
    const backdropMesh = new Mesh(backdropGeom, backdropMat);
    backdropMesh.position.set(0, 0, -3);
    backdropMesh.rotation.x = -Math.PI / 2;
    group.add(backdropMesh);

    // ---------- Text ----------
    // Headline
    const headlineMesh = ctx.fontAtlas.createText({
        text: config.textContent.headline,
        style: {
            family: 'Lora',
            size: 68,
            weight: 600,
            letterSpacing: -0.005,
            lineHeight: 1.1,
            color: '#e8ecf2'
        },
        atlasIndex: 0,
        sourceRect: { x: 0, y: 0, width: 512, height: 320 }
    });
    headlineMesh.position.set(0, -1.2, 0.1);
    group.add(headlineMesh);

    // Caption
    const captionMesh = ctx.fontAtlas.createText({
        text: config.textContent.caption,
        style: {
            family: 'JetBrains Mono',
            size: 18,
            weight: 400,
            letterSpacing: 0.08,
            lineHeight: 1.4,
            color: '#e8ecf2'
        },
        atlasIndex: 0,
        sourceRect: { x: 0, y: 0, width: 512, height: 320 }
    });
    captionMesh.position.set(0, -1.6, 0.1);
    group.add(captionMesh);

    // ---------- Cinematic Primitives ----------
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const primitive of config.cinematicPrimitives) {
            const fn = ctx.primitives[primitive.name];
            if (typeof fn === 'function') {
                fn(group, primitive.params);
            }
        }
    }

    // ---------- Handlers & Cleanup ----------
    group.userData.handlers = {};

    const timelines = [];

    // Example: a simple rise‑in animation for the whole group (optional)
    const riseTimeline = gsap.fromTo(
        group.position,
        { y: group.position.y - 0.4 },
        {
            y: group.position.y,
            duration: 0.7,
            ease: 'power3.out'
        }
    );
    timelines.push(riseTimeline);

    group.userData.cleanup = () => {
        // Dispose textures
        brushedTex.dispose();

        // Dispose materials
        pedestalMat.dispose();
        shadowMat.dispose();
        // Node‑based materials have .dispose()
        metalMatNode.dispose();
        backdropMatNode.dispose();

        // Kill GSAP timelines
        for (const tl of timelines) tl.kill();

        // Remove from parent if still attached
        if (group.parent) group.parent.remove(group);
    };

    return group;
}
